import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const Temples = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCity, setSelectedCity] = useState('all');
  const [selectedTemple, setSelectedTemple] = useState(null);

  const temples = [
    {
      id: 1,
      name: 'Somnath Temple',
      city: 'Veraval',
      image: 'https://girsomnath.nic.in/wp-content/uploads/2020/09/somnath-temple.jpg',
      history: `The Somnath temple is the first among the twelve Jyotirlinga shrines of Shiva, located in Prabhas Patan near Veraval. Destroyed 17 times by Muslim invaders and Portuguese, it was rebuilt in 1951 in Chalukya architectural style by Sardar Vallabhbhai Patel.

President Rajendra Prasad performed the Pran Pratishtha ceremony. The temple faces the Arabian Sea and stands as a symbol of India's resilience and Hindu devotion. Its 50m high shikhara is visible from 30km away.`,
      timings: '6AM - 9PM',
      distance: '320 km from Ahmedabad',
      facts: ['First of 12 Jyotirlingas', 'Rebuilt 1951 by Sardar Patel', 'Faces Arabian Sea']
    },
    {
      id: 2,
      name: 'Dwarka Temple',
      city: 'Dwarka',
      image: 'https://devbhumidwarka.nic.in/wp-content/uploads/2020/09/dwarkadhish-temple.jpg',
      history: `Dwarkadhish Temple (Jagat Mandir) was built 2500+ years ago by Vajranabh, Lord Krishna's grandson. One of Char Dham pilgrimage sites, its 78m tall spire is visible from 10km with a flag that never falls flat.

The temple has 72 pillars and stands on Gomti creek. Pilgrims enter through Swarga Dwar and exit via Moksha Dwar after climbing 56 steps. Continuous aarti happens every 15 minutes.`,
      timings: '6AM - 8:30PM',
      distance: '430 km from Ahmedabad',
      facts: ['2500+ years old', '78m tall spire', 'Char Dham pilgrimage']
    },
    {
      id: 3,
      name: 'Akshardham Temple',
      city: 'Gandhinagar',
      image: 'https://www.gujarattourism.com/images/akshardham-gandhinagar.jpg',
      history: `Built in 1992 without steel/iron using 6000 tons pink sandstone, Akshardham spans 23 acres. The 108ft central shikhara enshrines 7ft gold-leafed Swaminarayan murti surrounded by 97 intricately carved pillars.

17 domes depict Hindu epics. 20ft stone beams weigh 5 tons each. Features eternal river of 11,000 statues showing India's spiritual history from ancient times to independence.`,
      timings: '10AM - 7PM (Closed Mon)',
      distance: '25 km from Ahmedabad',
      facts: ['No steel used', '6000 tons pink sandstone', '23-acre complex']
    },
    {
      id: 4,
      name: 'Pavagarh Kalika Mata',
      city: 'Pavagarh',
      image: 'https://www.gujarattourism.com/images/pavagadh-kalika-mata.jpg',
      history: `UNESCO World Heritage site at 800m summit of Pavagadh hill, Kalika Mata Temple dates to 10th-11th century Hindu kings. Houses red-painted Mahakali mukhwato flanked by Bhadrakali and Bahuchara Mata shrines.

Pilgrims climb 2500+ steps or use ropeway. Adjacent Muslim shrine of Sadan Shah proves Hindu-Muslim harmony. Part of Champaner-Pavagadh Archaeological Park destroyed by Mahmud of Ghazni.`,
      timings: '5AM - 8PM',
      distance: '180 km from Ahmedabad',
      facts: ['UNESCO site', '10th century', '2500+ steps climb']
    },
    {
      id: 5,
      name: 'Ambaji Temple',
      city: 'Ambaji',
      history: `One of 51 Shakti Peeths where Maa Sati\'s heart fell, Ambaji on Arasur hill near Saraswati river origin is a major pilgrimage center. Original seat on Gabbar hill hosts world\'s largest mythological light & sound show.

Bhadarva Purnima mela attracts 5 million devotees. Navratri garba celebrations famous across Gujarat-Rajasthan border near Mount Abu. Houses sacred heart-shaped Shree Yantra.`,
      timings: '6AM - 9PM',
      distance: '190 km from Ahmedabad',
      facts: ['51 Shakti Peeth', 'Gabbar hill original', '5M Navratri mela']
    }
  ];

  const filteredTemples = temples.filter(temple => {
    const matchesSearch = temple.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         temple.city.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCity = selectedCity === 'all' || temple.city === selectedCity;
    return matchesSearch && matchesCity;
  });

  const cities = ['all', ...new Set(temples.map(t => t.city))];

  return (
    <div className="min-h-screen bg-gradient-to-br from-temple-beige to-white py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="text-center mb-16">
          <h1 className="text-4xl md:text-5xl font-bold bg-gradient-to-r from-temple-gold to-amber-600 bg-clip-text text-transparent mb-6">
            Sacred Temples of Gujarat
          </h1>
          <p className="text-xl text-temple-dark/70 max-w-2xl mx-auto">
            Explore rich history, architecture and spiritual significance
          </p>
        </div>

        {/* Filters */}
        <div className="bg-white/70 backdrop-blur-sm rounded-3xl p-8 shadow-2xl mb-12">
          <div className="flex flex-col lg:flex-row gap-6 items-center justify-between">
            <div className="relative flex-1 max-w-md">
              <input
                type="text"
                placeholder="Search temples or cities..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-12 pr-4 py-4 border border-gray-300 rounded-2xl focus:ring-3 focus:ring-temple-gold/50 focus:border-transparent transition-all text-lg"
              />
              <div className="absolute left-5 top-5 text-xl text-gray-400">🔍</div>
            </div>
            
            <div className="flex flex-wrap gap-3">
              {cities.map(city => (
                <button
                  key={city}
                  onClick={() => setSelectedCity(city)}
                  className={`px-6 py-3 rounded-2xl font-semibold transition-all duration-200 shadow-lg ${
                    selectedCity === city
                      ? 'bg-temple-gold text-white shadow-temple-gold/25'
                      : 'bg-white/60 hover:bg-white shadow-md text-gray-700'
                  }`}
                >
                  {city === 'all' ? 'All Cities' : city}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Temples Grid - HISTORY FOCUS */}
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredTemples.map((temple) => (
            <div
              key={temple.id}
              className="group bg-white/80 backdrop-blur-sm rounded-3xl overflow-hidden shadow-2xl hover:shadow-3xl transition-all duration-300 hover:-translate-y-3 cursor-pointer h-[650px] flex flex-col"
              onClick={() => setSelectedTemple(temple)}
            >
              {/* Temple Image - OFFICIAL GOVT */}
              <div className="h-80 relative overflow-hidden group-hover:scale-[1.02] transition-transform duration-500">
                <img 
                  src={temple.image} 
                  alt={temple.name}
                  className="w-full h-full object-cover"
                  onError={(e) => {
                    e.target.src = 'https://via.placeholder.com/400x320/amber/amber-200?text=Temple';
                  }}
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/30 via-transparent to-transparent" />
                <div className="absolute top-4 left-4 bg-white/90 px-3 py-1 rounded-xl text-sm font-semibold text-gray-800">
                  Official Photo
                </div>
              </div>

              {/* Temple Details */}
              <div className="p-8 flex-1 flex flex-col">
                <h3 className="text-2xl font-bold text-gray-900 mb-4 group-hover:text-temple-gold transition-colors">
                  {temple.name}
                </h3>
                
                <div className="flex items-center text-lg mb-4">
                  <span className="text-temple-gold mr-2">📍</span>
                  <span>{temple.city}, Gujarat</span>
                </div>

                {/* History - 1 viewport worth */}
                <div className="text-gray-700 mb-6 leading-relaxed text-base flex-1">
                  {temple.history}
                </div>

                {/* Facts Grid */}
                <div className="grid grid-cols-3 gap-2 mb-6">
                  {temple.facts.map((fact, idx) => (
                    <div key={idx} className="bg-gradient-to-r from-temple-gold/10 p-3 rounded-xl text-sm text-gray-800 border border-temple-gold/20">
                      {fact}
                    </div>
                  ))}
                </div>

                {/* Info Row */}
                <div className="grid grid-cols-2 gap-4 mb-6 text-sm">
                  <div className="flex items-center">
                    <span className="text-temple-gold mr-2">🕒</span>
                    <span>{temple.timings}</span>
                  </div>
                  <div className="flex items-center">
                    <span className="text-temple-gold mr-2">📏</span>
                    <span>{temple.distance}</span>
                  </div>
                </div>

                {/* Book Button - TO VIRTUAL QUEUE */}
                <Link
                  to="/virtual-queue"
                  className="w-full text-center py-4 px-8 bg-gradient-to-r from-temple-gold to-amber-600 hover:from-temple-gold/90 text-white font-bold rounded-2xl shadow-2xl hover:shadow-3xl transition-all duration-300 mt-auto"
                >
                  Book Darshan →
                </Link>
              </div>
            </div>
          ))}
        </div>

        {filteredTemples.length === 0 && (
          <div className="text-center py-24 col-span-full">
            <div className="w-32 h-32 bg-gray-100 rounded-3xl mx-auto mb-8 flex items-center justify-center">
              <span className="text-4xl">🛕</span>
            </div>
            <h3 className="text-2xl font-bold text-gray-900 mb-4">No temples found</h3>
            <p className="text-gray-600 mb-8 text-lg">Try adjusting your search or city filter</p>
            <button
              onClick={() => {
                setSearchTerm('');
                setSelectedCity('all');
              }}
              className="px-10 py-4 bg-temple-gold hover:bg-opacity-90 text-white font-bold text-lg rounded-2xl shadow-2xl hover:shadow-3xl transition-all"
            >
              Clear Filters
            </button>
          </div>
        )}

        {/* Stats */}
        <div className="grid md:grid-cols-3 gap-6 mt-20 mb-12">
          <div className="bg-white/70 backdrop-blur-sm p-8 rounded-2xl shadow-xl text-center">
            <div className="text-3xl font-bold text-temple-gold mb-2">{temples.length}</div>
            <div className="text-gray-600 font-semibold">Total Temples</div>
          </div>
          <div className="bg-white/70 backdrop-blur-sm p-8 rounded-2xl shadow-xl text-center">
            <div className="text-3xl font-bold text-blue-600 mb-2">{temples.length}</div>
            <div className="text-gray-600 font-semibold">With Rich History</div>
          </div>
          <div className="bg-white/70 backdrop-blur-sm p-8 rounded-2xl shadow-xl text-center">
            <div className="text-3xl font-bold text-emerald-600 mb-2">{filteredTemples.length}</div>
            <div className="text-gray-600 font-semibold">Showing Results</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Temples;
